public class StarPainterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String pixel(java.awt.image.BufferedImage img, int x, int y) {
        return String.format("#%06X", img.getRGB(x, y) & 0xFFFFFF);
    }

    static java.awt.image.BufferedImage render(int size, int points) {
        java.awt.image.BufferedImage img =
                new java.awt.image.BufferedImage(size, size, java.awt.image.BufferedImage.TYPE_INT_RGB);
        java.awt.Graphics2D g = img.createGraphics();
        try {
            StarPainter.paint(g, size, points);
        } finally {
            g.dispose();
        }
        return img;
    }

    public static void main(String[] args) {
        try {
            java.awt.image.BufferedImage five = render(200, 5);
            check("5-point: center is black (100,100)", "#000000", pixel(five, 100, 100));
            check("5-point: inside the upward tip (100,40)", "#000000", pixel(five, 100, 40));
            check("5-point: white notch between top tips (135,51)", "#FFFFFF", pixel(five, 135, 51));
            check("5-point: white below center between lower tips (100,150)", "#FFFFFF", pixel(five, 100, 150));
            check("5-point: background corner is white (10,10)", "#FFFFFF", pixel(five, 10, 10));
            java.awt.image.BufferedImage four = render(120, 4);
            check("4-point: center is black (60,60)", "#000000", pixel(four, 60, 60));
            check("4-point: inside the upward tip (60,25)", "#000000", pixel(four, 60, 25));
            check("4-point: white notch between tips (85,35)", "#FFFFFF", pixel(four, 85, 35));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

