import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Polygon;

public class StarPainter {

    public static void paint(Graphics2D g, int size, int points) {
        g.setColor(Color.WHITE);
        g.fillRect(0, 0, size, size);
        double cx = size / 2.0;
        double cy = size / 2.0;
        int outer = size / 2 - 2;
        int inner = size / 5;
        Polygon star = new Polygon();
        for (int k = 0; k < 2 * points; k++) {
            double angle = -Math.PI / 2 + k * Math.PI / points;
            int radius = (k % 2 == 0) ? outer : inner;
            star.addPoint((int) Math.round(cx + radius * Math.cos(angle)),
                          (int) Math.round(cy + radius * Math.sin(angle)));
        }
        g.setColor(Color.BLACK);
        g.fillPolygon(star);
    }
}
